433:    // Use xz command to decompress .xz files
434:    command = "xz -dc " + filePath;
435:  } else if (hasEnding(filePath, ".traceg")) {
436:    // Use cat command for regular trace files
437:    command = "cat " + filePath;
438:  } else {
439:    throw std::runtime_error("Unsupported file type!");
440:  }
441:
